# How the daemon reads SteamCMD output (ADR 0010). The wording changes between
# SteamCMD builds, so it is data: add a pattern here, not code. Output that
# matches no failure pattern is reported verbatim as `steam_unknown_error`.
#
# After editing, run `dart run tool/embed_steam_patterns.dart` from
# apps/yagurad; a test fails when the embedded copy is out of date.

# Version of this table; bump it when patterns change.
version: 2

# Steps the output moves through. The first line matching `match` starts the
# step; `steam_login` is also started by the daemon before SteamCMD prints.
steps:
  - step: steam_login
    match: 'Connecting anonymously|Logging in user|Logging in using cached credentials'

# Progress lines, for example
#   Update state (0x61) downloading, progress: 45.12 (1234 / 2736)
progress:
  match: 'Update state \(0x[0-9a-fA-F]+\) (?<state>[A-Za-z ]+?), progress: (?<percent>[0-9.]+) \((?<done>\d+) / (?<total>\d+)\)'
  # The step a progress state belongs to; the first match wins.
  states:
    - match: 'verifying|validating'
      step: verify
    - match: 'committing'
      step: commit
    - match: '.*'
      step: download

# Lines that mean the run succeeded.
success: "Success! App '\\d+' (fully installed|already up to date)"

# Failure lines, first match wins. `{app_id}` is the app being installed.
# `retry: once` runs the same SteamCMD command a second time before the
# failure is reported.
failures:
  # A freshly bootstrapped SteamCMD (build 1791918946) fails its first
  # app_update this way; the same command succeeds when run again.
  - id: missing_configuration
    reason: steam_unknown_error
    retry: once
    match: "Failed to install app '\\d+' \\(Missing configuration\\)"
    message: "SteamCMD could not install the app {app_id} (SteamCMD: Missing configuration), also when run a second time."
  - id: no_subscription
    reason: steam_no_subscription
    match: "Failed to install app '\\d+' \\(No subscription\\)"
    message: "The Steam account does not own the required app {app_id} (SteamCMD: No subscription)."
  - id: disk_write_failure
    reason: insufficient_disk
    match: "Failed to install app '\\d+' \\((Disk write failure|Not enough disk space)\\)"
    message: "SteamCMD could not write the app {app_id}: the volume is full or not writable."
''';
